<?php
declare(strict_types=1);
require __DIR__ . '/includes/auth.php';
require_auth();
$pageTitle = 'Dashboard';
$plate = substr(query_string('nomor_polisi'), 0, 80);
$owner = substr(query_string('nama_pemilik'), 0, 400);
$where = [];
$bindings = [];
// Pencarian literal: karakter % dan _ tidak menjadi wildcard masukan pengguna.
foreach (['nomor_polisi' => $plate, 'nama_pemilik' => $owner] as $column => $value) {
    if ($value !== '') {
        $where[] = "$column LIKE ? ESCAPE '!'";
        $bindings[] = '%' . str_replace(['!', '%', '_'], ['!!', '!%', '!_'], $value) . '%';
    }
}
$filter = $where ? ' WHERE ' . implode(' AND ', $where) : '';
$countStatement = db()->prepare('SELECT COUNT(*) FROM kendaraan' . $filter);
$countStatement->execute($bindings);
$filteredCount = (int) $countStatement->fetchColumn();
$perPage = 10;
$totalPages = max(1, (int) ceil($filteredCount / $perPage));
$page = min($totalPages, max(1, (int) query_string('page', '1')));
$offset = ($page - 1) * $perPage;
$query = db()->prepare('SELECT id, nomor_polisi, nama_pemilik, merek, tipe, jenis, tahun_pembuatan, berlaku_sampai, created_at FROM kendaraan' . $filter . " ORDER BY created_at DESC, id DESC LIMIT $perPage OFFSET $offset");
$query->execute($bindings);
$vehicles = array_map('uppercase_vehicle', $query->fetchAll());
$stats = db()->query('SELECT COUNT(*) AS total, SUM(DATE(created_at) = CURDATE()) AS today, SUM(berlaku_sampai >= CURDATE()) AS active FROM kendaraan')->fetch();
$recent = array_map('uppercase_vehicle', db()->query('SELECT id, nomor_polisi, nama_pemilik, merek, tipe, created_at FROM kendaraan ORDER BY created_at DESC, id DESC LIMIT 3')->fetchAll());
require __DIR__ . '/includes/header.php';
?>
<div class="page-heading"><div><div class="eyebrow">RUANG KERJA ANDA</div><h1>Dashboard<span class="heading-dot">.</span></h1><p>Pantau dan kelola seluruh data kendaraan Anda.</p></div><a class="btn btn-primary" href="tambah.php"><i class="bi bi-plus-lg"></i> Tambah data</a></div>
<section class="stats-grid" aria-label="Statistik kendaraan"><article class="stat-card"><div class="stat-top"><span>Total kendaraan</span><span class="stat-icon blue"><i class="bi bi-car-front"></i></span></div><strong><?= number_format((int) $stats['total'], 0, ',', '.') ?></strong><div class="stat-caption"><span class="mini-indicator"></span> Seluruh data tersimpan</div></article><article class="stat-card"><div class="stat-top"><span>Ditambahkan hari ini</span><span class="stat-icon violet"><i class="bi bi-calendar2-plus"></i></span></div><strong><?= (int) $stats['today'] ?></strong><div class="stat-caption">Pencatatan baru hari ini</div></article><article class="stat-card"><div class="stat-top"><span>Masa berlaku aktif</span><span class="stat-icon green"><i class="bi bi-check2-circle"></i></span></div><strong><?= number_format((int) $stats['active'], 0, ',', '.') ?></strong><div class="stat-caption">Berdasarkan tanggal berlaku</div></article></section>
<section class="panel data-panel"><div class="panel-heading"><div><h2>Data kendaraan <span class="count-badge"><?= (int) $stats['total'] ?></span></h2><p>Semua informasi kendaraan, dalam satu daftar.</p></div><span class="subtle-tag"><i class="bi bi-database-check"></i> Database internal</span></div>
<form class="search-toolbar" method="get" action="index.php"><div class="search-field"><i class="bi bi-search"></i><input class="form-control" name="nomor_polisi" aria-label="Cari nomor polisi" placeholder="Cari nomor polisi..." value="<?= e($plate) ?>" maxlength="20"></div><div class="search-field"><i class="bi bi-person"></i><input class="form-control" name="nama_pemilik" aria-label="Cari nama pemilik" placeholder="Cari nama pemilik..." value="<?= e($owner) ?>" maxlength="100"></div><button class="btn btn-outline-secondary" type="submit"><i class="bi bi-sliders2"></i> Cari data</button><?php if ($where): ?><a class="btn btn-link" href="index.php">Reset</a><?php endif; ?><span class="search-count"><?= $filteredCount ?> data ditemukan</span></form>
<div class="table-responsive"><table class="table vehicle-table align-middle"><thead><tr><th class="row-number">NO.</th><th>NOMOR POLISI</th><th>PEMILIK</th><th>KENDARAAN</th><th>MASA BERLAKU</th><th class="text-end">TINDAKAN</th></tr></thead><tbody>
<?php foreach ($vehicles as $index => $row): $active = $row['berlaku_sampai'] >= date('Y-m-d'); ?>
<tr><td class="text-muted"><?= $offset + $index + 1 ?></td><td><a class="plate" href="detail.php?id=<?= $row['id'] ?>"><?= e($row['nomor_polisi']) ?></a></td><td><a class="owner-name" href="detail.php?id=<?= $row['id'] ?>"><?= e($row['nama_pemilik']) ?></a><small class="cell-subtitle">Ditambahkan <?= e(format_date($row['created_at'])) ?></small></td><td><span class="vehicle-name"><?= e($row['merek'] . ' ' . $row['tipe']) ?></span><small class="cell-subtitle"><?= e($row['jenis']) ?> <span class="mx-1">·</span> <?= e($row['tahun_pembuatan']) ?></small></td><td><span class="date-value"><?= e(format_date($row['berlaku_sampai'])) ?></span><small class="status-label <?= $active ? 'is-active' : 'is-expired' ?>"><span></span><?= $active ? 'Aktif' : 'Berakhir' ?></small></td><td><div class="row-actions"><a class="icon-button" href="detail.php?id=<?= $row['id'] ?>" aria-label="Detail <?= e($row['nomor_polisi']) ?>" title="Detail"><i class="bi bi-eye"></i></a><a class="icon-button" href="edit.php?id=<?= $row['id'] ?>" aria-label="Edit <?= e($row['nomor_polisi']) ?>" title="Edit"><i class="bi bi-pencil-square"></i></a><a class="icon-button" href="preview.php?id=<?= $row['id'] ?>" aria-label="Preview <?= e($row['nomor_polisi']) ?>" title="Preview"><i class="bi bi-file-earmark-text"></i></a><a class="icon-button" href="print.php?id=<?= $row['id'] ?>" aria-label="Cetak ulang <?= e($row['nomor_polisi']) ?>" title="Print / cetak ulang"><i class="bi bi-printer"></i></a><form action="hapus.php" method="post" data-confirm="Hapus data <?= e($row['nomor_polisi']) ?>? Tindakan ini tidak dapat dibatalkan."><?= csrf_field() ?><input type="hidden" name="id" value="<?= $row['id'] ?>"><button class="icon-button danger" aria-label="Hapus <?= e($row['nomor_polisi']) ?>" title="Hapus"><i class="bi bi-trash3"></i></button></form></div></td></tr>
<?php endforeach; ?>
<?php if (!$vehicles): ?><tr><td colspan="6"><div class="empty-state"><span class="empty-icon"><i class="bi bi-car-front"></i></span><h3><?= $where ? 'Data belum ditemukan' : 'Mulai pencatatan pertama Anda' ?></h3><p><?= $where ? 'Coba nomor polisi atau nama pemilik yang lain.' : 'Tambahkan kendaraan untuk melihat data dan mulai mencetak lembar administrasi.' ?></p><a class="btn btn-primary btn-sm" href="<?= $where ? 'index.php' : 'tambah.php' ?>"><?= $where ? 'Tampilkan semua data' : 'Tambah kendaraan' ?> <i class="bi bi-arrow-right"></i></a></div></td></tr><?php endif; ?>
</tbody></table></div>
<div class="table-footer"><span>Menampilkan <strong><?= $filteredCount ? $offset + 1 : 0 ?>–<?= min($offset + $perPage, $filteredCount) ?></strong> dari <strong><?= $filteredCount ?></strong> data</span><nav class="pagination-nav" aria-label="Halaman data"><?php if ($page > 1): ?><a href="?<?= e(http_build_query(['nomor_polisi' => $plate, 'nama_pemilik' => $owner, 'page' => $page - 1])) ?>" aria-label="Halaman sebelumnya"><i class="bi bi-chevron-left"></i></a><?php endif; ?><?php for ($p = max(1, $page - 2); $p <= min($totalPages, $page + 2); $p++): ?><a class="<?= $p === $page ? 'active' : '' ?>" <?= $p === $page ? 'aria-current="page"' : '' ?> href="?<?= e(http_build_query(['nomor_polisi' => $plate, 'nama_pemilik' => $owner, 'page' => $p])) ?>"><?= $p ?></a><?php endfor; ?><?php if ($page < $totalPages): ?><a href="?<?= e(http_build_query(['nomor_polisi' => $plate, 'nama_pemilik' => $owner, 'page' => $page + 1])) ?>" aria-label="Halaman selanjutnya"><i class="bi bi-chevron-right"></i></a><?php endif; ?></nav></div></section>
<div class="dashboard-bottom"><section class="panel recent-panel"><div class="panel-heading"><div><h2>Baru ditambahkan</h2><p>Pencatatan kendaraan terbaru.</p></div><span class="round-icon"><i class="bi bi-clock-history"></i></span></div><div class="recent-list"><?php foreach ($recent as $row): ?><a class="recent-item" href="detail.php?id=<?= $row['id'] ?>"><span class="recent-icon"><i class="bi bi-car-front"></i></span><div><strong><?= e($row['nomor_polisi']) ?></strong><span><?= e($row['nama_pemilik']) ?> · <?= e($row['merek']) ?></span></div><small><?= e(format_date($row['created_at'])) ?></small><i class="bi bi-arrow-up-right"></i></a><?php endforeach; ?><?php if (!$recent): ?><p class="text-muted px-4 pb-4">Belum ada kendaraan yang ditambahkan.</p><?php endif; ?></div></section><section class="print-guide"><div class="guide-icon"><i class="bi bi-printer"></i></div><div class="eyebrow">SIAP UNTUK DICETAK</div><h2>Hasil rapi, ukuran presisi.</h2><p>Pilih kolom kiri, tengah, atau kanan untuk mencetak satu STNK pada lembar landscape.</p><a href="print-settings.php">Pilih posisi cetak <i class="bi bi-arrow-right"></i></a><span class="guide-spec">LANDSCAPE <span>·</span> ISI PORTRAIT</span></section></div>
